/** Accept only the URL generated by Google Maps' "Embed a map" dialog.
 * The URL is stored as data; HTML supplied by an administrator is never rendered.
 */
export function getGoogleMapsEmbedUrl(value: string): string | null {
  if (!value || value.length > 1500 || !/^https:\/\/www\.google\.com\/maps\/embed\?pb=/i.test(value)) return null;
  // Inspect before URL normalization, which can erase controls and a default port.
  if (/[\s\u0000-\u001f\u007f\\#<>"'`]/u.test(value) || /%(?:0[0-9a-f]|1[0-9a-f]|7f|5c)/i.test(value)) return null;
  if (/%(?![0-9a-f]{2})/i.test(value)) return null;
  try {
    const url = new URL(value);
    if (url.protocol !== 'https:' || url.hostname !== 'www.google.com' || url.port || url.username || url.password || url.hash || url.pathname !== '/maps/embed') return null;
    const parameters = [...url.searchParams.entries()];
    if (parameters.length !== 1 || parameters[0][0] !== 'pb' || !/^!.+/u.test(parameters[0][1])) return null;
    return value;
  } catch { return null; }
}

/** Maps embeds are not photo files and are supported only for the event venue. */
export function isGoogleMapsEmbedAddress(value: string): boolean {
  try {
    const url = new URL(value);
    return (url.hostname === 'google.com' || url.hostname.endsWith('.google.com')) && url.pathname.startsWith('/maps/embed');
  } catch { return false; }
}
